def run_custom_stack_ops(max_size, ops):
    stack = []
    increments = [0] * max_size
    output = []

    for op, arg in ops:
        if op == 'push':
            if len(stack) < max_size:
                stack.append(arg)
        elif op == 'pop':
            if not stack:
                output.append(-1)
            else:
                idx = len(stack) - 1
                val = stack[idx] + increments[idx]
                if idx > 0:
                    increments[idx - 1] += increments[idx]
                increments[idx] = 0
                stack.pop()
                output.append(val)
        elif op == 'increment':
            k, val = arg
            if stack:
                idx = min(k, len(stack)) - 1
                if idx >= 0:
                    increments[idx] += val

    return output

